//! Per-incarnation execution journal of the real vote runtime.
//! Ghost history is updated by actual constructors and handlers; it is not a
//! replacement for cluster provenance or durable cross-crash history.
use super::{protocol as p, state, storage};
use vstd::prelude::*;
verus! {
pub enum Origin { Fresh(usize, usize), Recovered(p::VoteImage) }
pub enum Input { Request(state::VoteRequest), Release(u64, p::VoteImage) }
pub enum Output { Submission(Option<(u64, p::VoteImage)>), Reply(Option<state::VoteReply>) }
pub struct History {
    pub origin: Origin,
    pub states: Seq<p::OperationView>,
    pub inputs: Seq<Input>,
    pub outputs: Seq<Output>,
}
pub open spec fn start(v: p::OperationView, origin: Origin) -> bool {
    p::view_invariant(v) && match origin {
        Origin::Fresh(me, members) => p::initial_view(v, me, members),
        Origin::Recovered(image) => p::image(v.state) == image && v.state.role == state::Role::Follower
            && v.pending.is_none() && v.serial == 0,
    }
}
pub open spec fn step(s: p::OperationView, i: Input, t: p::OperationView, o: Output) -> bool {
    match (i, o) {
        (Input::Request(q), Output::Submission(op)) => p::begin_step(s, q, t, op),
        (Input::Release(id, image), Output::Reply(reply)) => p::complete_step(s, id, image, t, reply),
        _ => false,
    }
}
pub open spec fn valid(h: History) -> bool {
    h.states.len() == h.inputs.len() + 1 && h.outputs.len() == h.inputs.len()
    && start(h.states[0], h.origin)
    && forall|k: int| 0 <= k < h.inputs.len() ==>
        step(h.states[k], #[trigger] h.inputs[k], h.states[k+1], h.outputs[k])
}
pub proof fn extend(h: History, i: Input, t: p::OperationView, o: Output) -> (next: History)
    requires valid(h), step(h.states.last(), i, t, o),
    ensures valid(next), next.states.last() == t,
        next.origin == h.origin, next.states == h.states.push(t),
        next.inputs == h.inputs.push(i), next.outputs == h.outputs.push(o),
{
    let next = History { origin: h.origin, states: h.states.push(t),
        inputs: h.inputs.push(i), outputs: h.outputs.push(o) };
    assert forall|k: int| 0 <= k < next.inputs.len() implies
        step(next.states[k], #[trigger] next.inputs[k], next.states[k+1], next.outputs[k]) by {
        if k < h.inputs.len() {
            assert(step(h.states[k], h.inputs[k], h.states[k+1], h.outputs[k]));
        } else { assert(k == h.inputs.len()); }
    }
    next
}

pub struct Runtime {
    core: p::Machine,
    journal: Ghost<History>,
}
impl Runtime {
    pub closed spec fn history(&self) -> History { self.journal@ }
    pub closed spec fn view(&self) -> p::OperationView { self.core.view() }
    pub closed spec fn invariant(&self) -> bool {
        self.core.invariant() && valid(self.journal@)
        && self.journal@.states.last() == self.core.view()
    }
    pub proof fn connected(&self)
        requires self.invariant(),
        ensures valid(self.history()), self.history().states.last() == self.view(),
            p::view_invariant(self.view()),
    { self.core.view_is_valid(); }

    pub fn new(me: usize, members: usize) -> (r: Option<Self>)
        ensures r.is_some() == (members > 0 && me < members),
            r.is_some() ==> r.unwrap().invariant()
                && r.unwrap().history().inputs.len() == 0
                && r.unwrap().history().origin == Origin::Fresh(me, members),
    {
        match p::Machine::new(me, members) {
            None => None,
            Some(core) => {
                proof { core.view_is_valid(); }
                let journal = Ghost(History { origin: Origin::Fresh(me, members),
                    states: seq![core.view()], inputs: Seq::empty(), outputs: Seq::empty() });
                Some(Self { core, journal })
            }
        }
    }
    pub fn recover(me: usize, members: usize, image: p::VoteImage) -> (r: Option<Self>)
        ensures r.is_some() ==> r.unwrap().invariant()
            && r.unwrap().history().origin == Origin::Recovered(image)
            && r.unwrap().history().inputs.len() == 0,
    {
        match p::Machine::recover(me, members, image) {
            None => None,
            Some(core) => {
                proof { core.view_is_valid(); }
                let journal = Ghost(History { origin: Origin::Recovered(image),
                    states: seq![core.view()], inputs: Seq::empty(), outputs: Seq::empty() });
                Some(Self { core, journal })
            }
        }
    }
    pub fn term(&self) -> (r: u64)
        requires self.invariant(),
        ensures r == self.view().state.term,
    { proof { self.core.view_is_valid(); } self.core.term() }
    pub fn is_leader(&self) -> (r: bool)
        requires self.invariant(),
        ensures r == (self.view().state.role == state::Role::Leader),
    { proof { self.core.view_is_valid(); } self.core.is_leader() }

    pub fn begin_vote(&mut self, q: state::VoteRequest) -> (op: Option<p::WriteVote>)
        requires old(self).invariant(),
        ensures self.invariant(),
            self.history().inputs == old(self).history().inputs.push(Input::Request(q)),
            self.history().states == old(self).history().states.push(self.view()),
            self.history().outputs == old(self).history().outputs.push(Output::Submission(
                match op { None => None, Some(w) => Some((w.number(), w.contents())) })),
    {
        let op = self.core.begin_vote(q);
        let ghost output = Output::Submission(match op { None => None,
            Some(ref w) => Some((w.number(), w.contents())) });
        self.journal = Ghost(extend(self.journal@, Input::Request(q), self.core.view(), output));
        op
    }
    pub fn release_vote(&mut self, written: storage::WrittenVote) -> (r: Option<state::VoteReply>)
        requires old(self).invariant(),
        ensures self.invariant(),
            self.history().inputs == old(self).history().inputs.push(Input::Release(written.id(), written.image())),
            self.history().states == old(self).history().states.push(self.view()),
            self.history().outputs == old(self).history().outputs.push(Output::Reply(r)),
    {
        let ghost input = Input::Release(written.id(), written.image());
        let r = written.release_reply(&mut self.core);
        self.journal = Ghost(extend(self.journal@, input, self.core.view(), Output::Reply(r)));
        r
    }
}
}
//! Actual per-incarnation constructor/handler-to-history connection.
//! PARTIAL: not yet the full cluster adapters consumed by requirements/final.rs.
//! No global theorem or crash-history completeness is claimed by this entry.
#[path = "durable_vote_reply.rs"]
pub mod durable_vote_reply;
pub use durable_vote_reply::storage_correspondence::{protocol, state, storage};
#[path = "../src/raft/execution.rs"]
pub mod executable;
use vstd::prelude::*;
verus! {
pub proof fn actual_runtime_is_connected(r: executable::Runtime)
    requires r.invariant(),
    ensures executable::valid(r.history()),
        r.history().states.last() == r.view(),
        protocol::view_invariant(r.view()),
{ r.connected(); }
}
//! Independent callers, DRAFT. Candidate types/relations are proof adapters.
//! Formula verification does not prove that actual host paths obey those relations.
#[path = "targets.rs"]
mod targets;
#[path = "support.rs"]
mod support;
#[path = "../madraft/proof/implementation.rs"]
mod implementation;
use vstd::prelude::*;
use implementation as c;

verus! {
pub type Execution = support::History<c::State, c::Input, c::Output, c::Message>;
pub open spec fn execution(h: Execution) -> bool {
    support::valid(h, |s| c::initial(s), |s,i,t,o| c::step(s,i,t,o), |i| c::receive(i), |o| c::emit(o))
}
// runtime interface begin
pub type RuntimeExecution = support::History<c::RuntimeState, c::Input, c::Output, c::Message>;
pub open spec fn runtime_execution(h: RuntimeExecution) -> bool {
    support::valid(h, |s| c::runtime_initial(s), |s,i,t,o| c::runtime_step(s,i,t,o), |i| c::receive(i), |o| c::emit(o))
}
pub open spec fn abstract_execution(h: RuntimeExecution) -> Execution {
    support::project(h, |s| c::view(s))
}
// runtime interface end
// obligation: election_safety
pub proof fn election_safety(run: Execution)
    requires execution(run),
    ensures targets::election_safety(c::observe(run)),
{ c::prove_election_safety(run); }

// obligation: leader_append_only
pub proof fn leader_append_only(run: Execution)
    requires execution(run),
    ensures targets::leader_append_only(c::observe(run)),
{ c::prove_leader_append_only(run); }

// obligation: log_matching
pub proof fn log_matching(run: Execution)
    requires execution(run),
    ensures targets::log_matching(c::observe(run)),
{ c::prove_log_matching(run); }

// obligation: leader_completeness
pub proof fn leader_completeness(run: Execution)
    requires execution(run),
    ensures targets::leader_completeness(c::observe(run)),
{ c::prove_leader_completeness(run); }

// obligation: state_machine_safety
pub proof fn state_machine_safety(run: Execution)
    requires execution(run),
    ensures targets::state_machine_safety(c::observe(run)),
{ c::prove_state_machine_safety(run); }

// This theorem proves relation-to-relation simulation. Real function/caller coverage
// is separate evidence; identical relations or imports alone cannot establish it.
// obligation: execution_link
pub proof fn execution_link(run: RuntimeExecution)
    requires runtime_execution(run),
    ensures execution(abstract_execution(run)),
        abstract_execution(run).inputs == run.inputs,
        abstract_execution(run).outputs == run.outputs,
        abstract_execution(run).sent == run.sent,
{
    assert forall|s: c::RuntimeState| c::runtime_initial(s) implies
        #[trigger] c::runtime_invariant(s, Seq::empty()) && c::initial(c::view(s)) by {
        c::prove_runtime_initial(s);
    }
    assert forall|s: c::RuntimeState, i: c::Input, t: c::RuntimeState, o: c::Output,
        a: Seq<support::Envelope<c::Message>>, b: Seq<support::Envelope<c::Message>>|
        #[trigger] c::runtime_invariant(s,a) && #[trigger] c::runtime_step(s,i,t,o)
        && #[trigger] support::exchange(a,c::receive(i),c::emit(o),b)
        implies c::runtime_invariant(t,b) && c::step(c::view(s),i,c::view(t),o) by {
        c::prove_runtime_step(s,i,t,o,a,b);
    }
    support::simulate(run, |s| c::runtime_initial(s), |s,i,t,o| c::runtime_step(s,i,t,o),
        |s| c::initial(s), |s,i,t,o| c::step(s,i,t,o), |i| c::receive(i), |o| c::emit(o),
        |s| c::view(s), |s,sent| c::runtime_invariant(s,sent));
}

// Formula coverage only: a model with no snapshots can satisfy this property.
// Actual creation/installation/recovery/decoding remain separate obligations.
// obligation: snapshot_observation
pub proof fn snapshot_and_observation_shape(run: Execution)
    requires execution(run),
    ensures targets::shape(c::observe(run)),
        targets::snapshot_fidelity(c::observe(run), c::applications()),
{ c::prove_observation_and_snapshots(run); }

// obligation: nonempty_execution
// Necessary witness from executable-side initialization/steps, not coverage by itself.
pub proof fn nonempty_execution()
    ensures exists|run: RuntimeExecution| runtime_execution(run)
        && targets::shape(c::observe(abstract_execution(run)))
        && exists|i: int| 0 <= i < c::observe(abstract_execution(run)).events.len()
            && !(c::observe(abstract_execution(run)).events[i] is Silent),
{
    let run = c::execution_witness();
    assert(runtime_execution(run));
    assert(targets::shape(c::observe(abstract_execution(run))));
    assert(exists|i: int| 0 <= i < c::observe(abstract_execution(run)).events.len()
        && !(c::observe(abstract_execution(run)).events[i] is Silent));
}

// Conditional on the supplied runtime relation describing every actual execution.
// obligation: composed_safety
pub proof fn actual_execution_safety(run: RuntimeExecution)
    requires runtime_execution(run),
    ensures targets::election_safety(c::observe(abstract_execution(run))),
        targets::leader_append_only(c::observe(abstract_execution(run))),
        targets::log_matching(c::observe(abstract_execution(run))),
        targets::leader_completeness(c::observe(abstract_execution(run))),
        targets::state_machine_safety(c::observe(abstract_execution(run))),
        targets::shape(c::observe(abstract_execution(run))),
        targets::snapshot_fidelity(c::observe(abstract_execution(run)), c::applications()),
{
    execution_link(run);
    let h = abstract_execution(run);
    election_safety(h); leader_append_only(h); log_matching(h);
    leader_completeness(h); state_machine_safety(h);
    snapshot_and_observation_shape(h);
}
} // verus!
